from collections import namedtuple
Stone = namedtuple('Stone', ['s', 'i'])

def debug(*args, **kwargs):
	import sys

def solve(n, s, t):
	s = list(map(lambda s_i: Stone(s_i[1], s_i[0]), enumerate(s)))
	t = t[:]
	s.sort()
	t.sort()
	diff = [s_.s - t_ for (s_, t_) in zip(s, t)]
	j = 0
	while j < n and diff[j] <= 0:
		j += 1
	moves = []
	for i in range(n):
		if diff[i] == 0:
			continue
		if diff[i] > 0:
			return (None, None)
		while j < n and -diff[i] >= diff[j]:
			moves.append((s[i].i, s[j].i, diff[j]))
			diff[i] += diff[j]
			diff[j] = 0
			while j < n and diff[j] <= 0:
				j += 1
		if diff[i] != 0:
			if j == n:
				return (None, None)
			moves.append((s[i].i, s[j].i, -diff[i]))
			diff[j] -= -diff[i]
			diff[i] = 0
	return (len(moves), moves)

def check(n, s, t, m, moves):
	s = s[:]
	t = t[:]
	for (i, j, d) in moves:
		debug(i=i, j=j, d=d, s=s)
		assert d > 0 and s[j] - s[i] >= 2 * d
		s[i] += d
		s[j] -= d
	debug(s=s, t=t)
	s.sort()
	t.sort()
	assert s == t

def main():
	n = int(input())
	s = list(map(int, input().split()))
	t = list(map(int, input().split()))
	(m, moves) = solve(n, s, t)
	if m is None:
		print('NO')
		return
	print('YES')
	print(m)
	for (i, j, d) in moves:
		print(i + 1, j + 1, d)
main()
